CREATE ROLE anon;
CREATE ROLE authenticated;
CREATE ROLE service_role;
CREATE SCHEMA auth;
CREATE FUNCTION auth.uid() RETURNS uuid LANGUAGE sql AS $$ SELECT nullif(current_setting('test.uid',true),'')::uuid $$;
CREATE FUNCTION fn_caller_is_engine() RETURNS boolean LANGUAGE sql AS $$ SELECT coalesce(current_setting('test.engine',true),'false')='true' $$;
CREATE FUNCTION fn_is_platform_admin() RETURNS boolean LANGUAGE sql AS $$ SELECT false $$;
CREATE TABLE staff(user_id uuid,club_id uuid);
CREATE FUNCTION fn_is_club_admin_uid(uuid) RETURNS boolean LANGUAGE sql SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM staff WHERE user_id=auth.uid() AND club_id=$1) $$;
CREATE FUNCTION is_admin() RETURNS boolean LANGUAGE sql AS $$ SELECT false $$;
CREATE TABLE club_members(user_id uuid,club_id uuid,role text);
CREATE TABLE agents(id uuid PRIMARY KEY,user_id uuid,club_id uuid,credit_used numeric,is_prepaid boolean);
CREATE TABLE credit_invoices(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),agent_id uuid,period_start timestamptz,period_end timestamptz,debt_owed numeric,amount_paid numeric,amount_remaining numeric,status text,due_date timestamptz,created_at timestamptz DEFAULT now(),paid_at timestamptz,UNIQUE(agent_id,period_end));
GRANT USAGE ON SCHEMA public,auth TO authenticated,service_role;
